import{_ as i,a,b as o}from"./chunks/OOP2values.BXGNZAUw.js";import{_ as r}from"./chunks/Install17.CwCXrGHM.js";import{_ as t,o as s,c as n,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Libre 2","description":"","frontmatter":{"source_hash":"6cdbd15c0c","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/libre2.md","filePath":"it/troubleshoot/libre2.md"}'),p={name:"it/troubleshoot/libre2.md"};function c(d,e,u,h,m,v){return s(),n("div",null,[...e[0]||(e[0]=[l('<div class="info custom-block"><p class="custom-block-title">Libre 2 UE</p><p>xDrip supporta solo la versione europea di Libre 2.<br> Se vuoi usare un Libre 2 di un&#39;altra area geografica, puoi far inviare i dati a xDrip da <a href="./../install/libre2patch.html">un&#39;altra app</a>.</p></div><br><h2 id="patched-app" tabindex="-1">App patchata <a class="header-anchor" href="#patched-app" aria-label="Permalink to &quot;App patchata {#patched-app}&quot;">​</a></h2><p>In Europa puoi creare la tua app patchata in conformità con la direttiva 2009/24/CE art. 6 (l&#39;applicazione può variare da paese a paese). La Germania ha un&#39;eccezione nel capitolo 6 dell&#39;EULA dell&#39;app del produttore.<br> La distribuzione dell&#39;app patchata non è autorizzata.</p><p>Trovi le spiegazioni su come generare l&#39;app cercando <code>xDrip-Patch</code> su <a href="https://github.com/search" target="_blank" rel="noreferrer">GitHub</a>.</p><p>Il sensore attuale deve essere avviato con l&#39;app patchata perché l&#39;app possa collegarsi.<br> Il Bluetooth del telefono deve essere attivato e i prerequisiti dell&#39;app soddisfatti <strong>prima</strong> di avviare il sensore. Se hai avviato un sensore senza i prerequisiti corretti, potresti non riuscire ad attivare gli allarmi e quindi a ricevere dati.</p><p>xDrip riceverà automaticamente i dati dall&#39;app patchata usando la sorgente dati hardware specifica <a href="./../install/libre2patch.html">Libre2 (patched App)</a>.</p><h4 id="check-connection" tabindex="-1">Verificare la connessione <a class="header-anchor" href="#check-connection" aria-label="Permalink to &quot;Verificare la connessione {#check-connection}&quot;">​</a></h4><p>L&#39;app patchata deve essere collegata al sensore perché xDrip possa riceverne i dati. Di solito, quando non lo è, vedi un punto esclamativo in alto a sinistra.</p><img src="'+i+'" style="zoom:75%;"><p>Se il sistema funzionava correttamente e questo è successo all&#39;improvviso, prova a riavviare il telefono, a metterlo in modalità aereo, a spegnere e riaccendere il Bluetooth per vedere se la connessione si ripristina.</p><p>Scansionare il sensore può essere una buona idea. Se il sensore non fornisce dati dopo la scansione, potrebbe essere difettoso.</p><p>Aprire il menu può darti informazioni sui prerequisiti mancanti perché l&#39;app si colleghi al sensore.</p><h4 id="prerequisites-to-connection" tabindex="-1">Prerequisiti per la connessione <a class="header-anchor" href="#prerequisites-to-connection" aria-label="Permalink to &quot;Prerequisiti per la connessione {#prerequisites-to-connection}&quot;">​</a></h4><ul><li>Il servizio di localizzazione di Android deve essere consentito, <strong>Sempre</strong>. Consenti sempre l&#39;app patchata (esempio qui sotto per xDrip)<br><img src="'+r+'" style="zoom:80%;"></li><li>Il telefono deve essere impostato su <a href="./../install/prerequisites.html#phone-time-accuracy">data, ora e fuso orario automatici</a></li><li>Almeno uno dei tre allarmi <strong>deve essere attivato</strong> nell&#39;app patchata</li><li>Il Bluetooth deve essere <strong>acceso</strong></li><li>Sveglie e promemoria (suoni) devono essere <strong>autorizzati</strong> (Impostazioni Android - App)</li><li>Le notifiche devono essere <strong>autorizzate</strong> (Impostazioni Android - App)</li><li>Le notifiche sulla schermata di blocco devono essere <strong>autorizzate</strong> (Impostazioni Android - App)</li></ul><br><h2 id="direct-connection" tabindex="-1">Connessione diretta <a class="header-anchor" href="#direct-connection" aria-label="Permalink to &quot;Connessione diretta {#direct-connection}&quot;">​</a></h2><p>Quando provi per la prima volta a collegare xDrip direttamente a un sensore Libre 2 e non sei sicuro di riuscire a far funzionare il sistema, è vivamente consigliato farlo l&#39;ultimo giorno del sensore attuale.<br> xDrip non rompe il sensore, impedisce solo all&#39;app del produttore o al lettore di ricevere gli allarmi; se fai affidamento su questi, potresti ritrovarti con un sensore che si comporta come un Libre 1.</p><p>Trovi altre informazioni su Libre 2 direct <a href="./libre2direct.html">qui</a></p><h4 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h4><p>Il dispositivo con cui hai avviato il sensore deve essere schermato (forno a microonde, spento) per evitare che interferisca con il processo di associazione di xDrip. Mostrerà l&#39;icona di connessione persa.</p><img src="'+a+'" style="zoom:75%;"><p>Se hai installato xDrip sullo stesso telefono con cui hai avviato e scansionato il sensore, si consiglia di disinstallare l&#39;app del produttore, perché ti impedirà di collegarti al Bluetooth del sensore e interferirà con le scansioni NFC. Puoi reinstallare l&#39;app quando xDrip è collegato al sensore; ovviamente non avrà più gli allarmi del sensore.</p><p>Se non vuoi rimuovere l&#39;app del produttore, devi disattivarne l&#39;autorizzazione alla posizione nelle impostazioni di Android.<br><strong>xDrip deve essere autorizzato, sempre.<br> L&#39;app del produttore NON deve essere autorizzata, mai.</strong></p><p>Nota che se tieni l&#39;app del produttore sul telefono, ogni volta che scansioni il sensore con NFC dovrai scegliere tra questa e xDrip. Questo può generare errori di lettura in xDrip.</p><h4 id="sensor-scan-errors" tabindex="-1">Errori di scansione del sensore <a class="header-anchor" href="#sensor-scan-errors" aria-label="Permalink to &quot;Errori di scansione del sensore {#sensor-scan-errors}&quot;">​</a></h4><p>Assicurati di aver <a href="./../install/libreNFC.html#configure-nfc">configurato</a> correttamente l&#39;NFC di xDrip.<br> Con xDrip la scansione richiede più tempo. Una volta trovata la posizione corretta dell&#39;antenna NFC del telefono, mettiti nel punto giusto e resta fermo.<br> Non puoi fare una scansione prima che siano passati 30 secondi dalla precedente.</p><h4 id="cannot-connect-to-the-sensor" tabindex="-1">Impossibile collegarsi al sensore <a class="header-anchor" href="#cannot-connect-to-the-sensor" aria-label="Permalink to &quot;Impossibile collegarsi al sensore {#cannot-connect-to-the-sensor}&quot;">​</a></h4><p>Verifica che <a href="./../use/OOP.html#oop2">OOP2</a> sia installato, attiva <a href="./../use/misc.html#oop2">nessuna calibrazione</a>, <a href="./../use/stopsensor.html#libre">ferma il sensore</a> e ricomincia da <a href="./../install/libre2.html#connect-to-the-sensor">qui</a>.</p><p>Scansiona ripetutamente ogni 2 minuti per 10 minuti, poi lascia stare il sistema per 20 minuti.</p><p>Dopo scansioni ripetute dovresti vedere dei valori in xDrip.<br> Dovresti vedere dei valori anche nell&#39;app OOP2.</p><img src="'+o+'" style="zoom:74%;"><p>Se non vedi valori dopo la scansione:</p><ul><li>Verifica di <strong>NON</strong> aver attivato <a href="./../use/misc.html#out-of-process-algorithm">OOP1</a> per errore</li><li>Assicurati che xDrip abbia l&#39;<a href="./../install/install.html#enable-location">accesso alla posizione autorizzato</a>, <strong>sempre</strong></li><li>Riavvia il telefono e riprova</li></ul><br><p>Se necessario, consulta la pagina di <a href="./librebridge.html">risoluzione problemi</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.06.15" target="_blank" rel="noreferrer"><em>Ultima modifica 18/06/2023</em></a></p>',38)])])}const q=t(p,[["render",c]]);export{z as __pageData,q as default};
